import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { _useSharedProgressBarPropsContext } from './hooks/useProgressBarPropsContext.js';
import { progressBarLabelCSS } from './ProgressBarLabel.sty.js';
import { _isStringChildren } from '../../../core/utils/is-string-children.js';
import { textStyleCSS } from '../../../styles/textStyle.sty.js';
import type { DataTestId } from '../../types/data-props.js';
import type { StylingProps } from '../../types/styling-props.js';
import type { WithChildren } from '../../types/with-children.js';

/** Accepted properties for ProgressBarLabel */
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface ProgressBarLabelProps
  extends WithChildren,
    StylingProps,
    DataTestId {}

/** ProgressBarLabel sub-component is rendered inside ProgressBar component. */
export const ProgressBarLabel = forwardRef<
  HTMLLabelElement,
  ProgressBarLabelProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: ProgressBarLabelProps = props;

  const { id, variant, density } = _useSharedProgressBarPropsContext();

  const childIsText = _isStringChildren(children);

  return (
    <label
      data-testid={dataTestId}
      ref={forwardedRef}
      htmlFor={id}
      className={clsx(
        consumerClassName,
        progressBarLabelCSS({ variant, size: density, childIsText }),
        textStyleCSS({ textStyle: 'base' }),
      )}
      style={consumerStyle}
      {...remainingProps}
    >
      {children}
    </label>
  );
});

(
  ProgressBarLabel as typeof ProgressBarLabel & { displayName: string }
).displayName = 'ProgressBar.Label';
